import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';

// Mock data for the flow demonstration
const mockAppointmentData = {
    date: 'Dec 10',
    time: '10:00 AM',
    hasTransportBooked: false,
};

// /frontend-react/src/App.js

// ... (imports remain the same)

function App() {
    // ... (state hooks remain the same)
    
    // We remove the mode switch button and hardcode isEasyMode to true for the demo, 
    // simulating a user already logged in via Easy Mode.
    const [isEasyMode, setIsEasyMode] = useState(true); 

    // This state now tracks the main medical sub-page
    const [medicalPage, setMedicalPage] = useState('medical-dashboard'); // 'medical-dashboard', 'appointment', 'transport', 'medicine'
    
    // Rework renderPage logic to handle the sub-navigation
    const renderPage = () => {
        // ... (existing logic for 'appointment', 'transport')

        // New logic for the Medical Sub-Dashboard
        if (medicalPage === 'medical-dashboard') {
            return (
                <MedicalDashboard
                    isEasyMode={isEasyMode}
                    goToPage={setMedicalPage} // Pass setter to allow navigation to sub-pages
                />
            );
        }
        
        // ... (render logic for other pages)
    };

    return (
        // New structure: mobile-container wraps all content
        <div style={{
            maxWidth: '400px', // Typical phone width
            height: '800px',   // Typical phone height
            margin: '20px auto', // Center the phone on the screen
            border: '8px solid #333',
            borderRadius: '25px',
            boxShadow: '0 0 20px rgba(0,0,0,0.5)',
            overflow: 'hidden', // Keeps content inside the frame
            backgroundColor: '#fff'
        }}>
            {/* The actual content of the app */}
            <div className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}>
                {/* Removed the mode switch button */}
                
                {/* Mock Notification Logic */}
                {/* If we are on the main dashboard, show the notification */}
                {page === 'dashboard' && (
                    <div 
                        onClick={handleNotificationClick} // This should now go to the appointment flow
                        style={{ /* ... (notification styling) ... */ }}
                    >
                        🚨 **NOTIFICATION: Appointment Soon! Tap Here!**
                    </div>
                )}
                
                {renderPage()}
            </div>
        </div>
    );
}

// ... (export App)

export default App;
